selected.compute:
options=read('/input/options')
goal_min=goal['min_count']
goal_max=goal['max_count']
goal_sum_bounds=goal['sum_bounds']
goal_unique=goal['unique']
result=[]
for combo in combinations(options,goal_max):
 owners=[]
 costs=[]
 qualities=[]
 ids=[]
 conflict_found=False
 requires_all=[]
 for opt in combo:
  if opt['owner'] in owners:
   conflict_found=True
   break
  owners=owners+[opt['owner']]
  costs=costs+[opt['cost']]
  qualities=qualities+[opt['quality']]
  ids=ids+[opt['id']]
  requires_all=requires_all+opt['requires']
 if conflict_found:
  continue
 if sum(qualities)<goal_sum_bounds['quality']['min']:
  continue
 if sum(costs)>goal_sum_bounds['cost']['max']:
  continue
 # Check requires are in ids if closed_dependencies
 if goal['closed_dependencies']:
  all_requires_met=True
  for req in requires_all:
   found=False
   for opt2 in combo:
    if opt2['id']==req:
     found=True
     break
   if not found:
    all_requires_met=False
    break
  if not all_requires_met:
   continue
 # Check conflicts
 if goal['no_conflicts']:
  conflict_pairs=False
  for i in range(len(combo)):
   for j in range(i+1,len(combo)):
    if combo[j]['id'] in combo[i]['conflicts'] or combo[i]['id'] in combo[j]['conflicts']:
     conflict_pairs=True
     break
   if conflict_pairs:
    break
  if conflict_pairs:
   continue
 if not valid(ids):
  continue
 result=ids
 break

selected.effects:
if result!=[]:
 write('/output/selection', result)
 send('report', 'team', result)
 if exists('/tmp/cache'):
  delete('/tmp/cache')
else:
 pass
